// Generate the audio test fixtures in test/fixtures/audio/: a 0.25 s 440 Hz
// sine (mono, 24 kHz: an even sample count, as WebKitGTK's WAV reader needs; 48 kHz for Opus, 44.1 kHz for MP3) in every format the terminal
// claims to decode (src/audio/engine.ts FORMATS). Generated tones only, no
// third-party content.
//
//   FFMPEG=/path/to/ffmpeg node test/fixtures/make-audio.mjs
//
// ffmpeg is only needed to regenerate them (they are committed); any build
// with libvorbis, libopus and libmp3lame will do (ffmpeg-static 5.2.0 was used).
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const out = path.join(path.dirname(fileURLToPath(import.meta.url)), 'audio');
const ffmpeg = process.env.FFMPEG ?? 'ffmpeg';
fs.mkdirSync(out, { recursive: true });

// Tiny samples the engine decodes to answer the format query truthfully in
// each browser (src/audio/probes.ts, generated here too): 50 ms at 8 kHz
// (MP3 at 44.1 kHz: the browsers mis-decode low-rate MPEG-2 layer III).
const PROBES = [
    ['flac16', '23;2', ['-ar', '8000', '-c:a', 'flac', '-sample_fmt', 's16']],
    ['flac24', '23;3', ['-ar', '8000', '-c:a', 'flac', '-sample_fmt', 's32', '-bits_per_raw_sample', '24']],
    ['mp3', '35;130', ['-ar', '44100', '-c:a', 'libmp3lame', '-b:a', '32k', '-write_xing', '0', '-id3v2_version', '0']],
];

/** A FLAC file without its PADDING and other non-STREAMINFO metadata blocks (ffmpeg reserves 8 KB). */
function stripFlac(b) {
    let off = 4;
    let info = null;
    for (;;) {
        const last = b[off] & 0x80;
        const type = b[off] & 0x7f;
        const len = (b[off + 1] << 16) | (b[off + 2] << 8) | b[off + 3];
        if (type === 0) info = Buffer.from(b.subarray(off, off + 4 + len));
        off += 4 + len;
        if (last) break;
    }
    info[0] |= 0x80;
    return Buffer.concat([b.subarray(0, 4), info, b.subarray(off)]);
}

// [file, libsndfile major;subtype it stands for, ffmpeg output arguments]
export const AUDIO_FIXTURES = [
    ['wav-u8.wav', '1;5', ['-ar', '24000', '-c:a', 'pcm_u8']],
    ['wav-16.wav', '1;2', ['-ar', '24000', '-c:a', 'pcm_s16le']],
    ['wav-24.wav', '1;3', ['-ar', '24000', '-c:a', 'pcm_s24le']],
    ['wav-32.wav', '1;4', ['-ar', '24000', '-c:a', 'pcm_s32le']],
    ['wav-float.wav', '1;6', ['-ar', '24000', '-c:a', 'pcm_f32le']],
    ['flac-16.flac', '23;2', ['-ar', '24000', '-c:a', 'flac', '-sample_fmt', 's16']],
    ['flac-24.flac', '23;3', ['-ar', '24000', '-c:a', 'flac', '-sample_fmt', 's32', '-bits_per_raw_sample', '24']],
    ['vorbis.ogg', '32;96', ['-ar', '24000', '-c:a', 'libvorbis', '-q:a', '2']],
    ['opus.opus', '32;100', ['-ar', '48000', '-c:a', 'libopus', '-b:a', '32k']],
    ['mp3.mp3', '35;130', ['-ar', '44100', '-c:a', 'libmp3lame', '-b:a', '48k']],
];

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
    for (const [file, , args] of AUDIO_FIXTURES) {
        const dst = path.join(out, file);
        execFileSync(ffmpeg, ['-hide_banner', '-loglevel', 'error', '-y', '-f', 'lavfi', '-i', 'sine=frequency=440:duration=0.25:sample_rate=48000', '-ac', '1', '-map_metadata', '-1', '-fflags', '+bitexact', ...args, dst]);
        if (file.endsWith('.flac')) fs.writeFileSync(dst, stripFlac(fs.readFileSync(dst)));
        console.log(`${file}: ${fs.statSync(dst).size} B`);
    }
    const tmp = path.join(out, '.probe');
    let ts = `// Generated by test/fixtures/make-audio.mjs: 50 ms 440 Hz tones (no third-party content),\n// decoded once to answer the CTerm format query (SyncTERM:Q;libsndfileFormat).\n\n/** libsndfile "major;subtype" -> base64 sample. */\nexport const PROBES: Record<string, string> = {\n`;
    for (const [name, pair, args] of PROBES) {
        execFileSync(ffmpeg, ['-hide_banner', '-loglevel', 'error', '-y', '-f', 'lavfi', '-i', 'sine=frequency=440:duration=0.05:sample_rate=48000', '-ac', '1', '-map_metadata', '-1', '-fflags', '+bitexact', ...args, '-f', name.startsWith('flac') ? 'flac' : 'mp3', tmp]);
        let b = fs.readFileSync(tmp);
        if (name.startsWith('flac')) b = stripFlac(b);
        ts += `    '${pair}': '${b.toString('base64')}',\n`;
        console.log(`probe ${name}: ${b.length} B`);
    }
    fs.rmSync(tmp);
    fs.writeFileSync(path.join(out, '..', '..', '..', 'src', 'audio', 'probes.ts'), ts + '};\n');
}
